INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (4, 1531368830, 'ASKA', 'Haha, aku ASKA! 😊 Aku sini untuk membantu kamu dengan pertanyaan atau informasi yang kamu butuhkan! 🤗', 'aska', '2025-12-01 09:38:20.121903+0700', 3984, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (5, 1531368830, 'fajartester', 'kamu kerja unntuk sapa?', 'user', '2025-12-01 09:38:31.577986+0700', NULL, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (6, 1531368830, 'ASKA', 'Haha, aku ASKA! 🤗 Aku bekerja untuk membantu kamu, teman-teman, dan semua orang yang membutuhkan informasi atau bantuan! 🤖✨', 'aska', '2025-12-01 09:38:32.628291+0700', 3884, NULL, 'telegram') ON CONFLICT DO NOTHING;
