INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (8, 1531368830, 'ASKA', 'Aku bekerja di Agent AI Sekolah Kita 🏫🤖✨! Aku disini untuk membantu kamu dengan segala hal yang terkait dengan sekolah dan pendidikan! 📚', 'aska', '2025-12-01 09:39:01.082243+0700', 3964, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (9, 1531368830, 'fajartester', 'apa kamu tau suku dinas pendidikan jakarta utara 2?', 'user', '2025-12-01 09:40:02.434994+0700', NULL, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (10, 1531368830, 'ASKA', 'Ya, aku tahu! 🤓 Aku ASKA! Suku Dinas Pendidikan Jakarta Utara 2 adalah salah satu unit kerja di Dinas Pendidikan Provinsi DKI Jakarta yang membina dan mengoordinasikan satuan pendidikan di sebagian wilayah Kota Administrasi Jakarta Utara! 🏙️', 'aska', '2025-12-01 09:40:03.348511+0700', 4435, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (11, 1531368830, 'fajartester', 'apa hubungannya denganmu?', 'user', '2025-12-01 09:40:20.662233+0700', NULL, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (12, 1531368830, 'ASKA', 'Aku ASKA! 🤗 Aku dikonfigurasi untuk membantu dan melayani kebutuhan informasi dan layanan pendukung di lingkungan Suku Dinas Pendidikan Jakarta Utara 2! 📚 Jadi, aku bisa membantu kamu dengan pertanyaan atau masalah yang terkait dengan Suku Dinas Pendidikan Jakarta Utara 2! 🤝', 'aska', '2025-12-01 09:40:22.399049+0700', 4669, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (13, 1531368830, 'fajartester', 'sapa kamu? dan kerja di instansi mana?', 'user', '2025-12-01 09:51:14.356921+0700', NULL, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (14, 1531368830, 'ASKA', 'Halo! 🤗 Aku ASKA! 🤗 Aku bekerja di sekolah, dan aku disiapkan untuk membantu kamu dengan informasi dan layanan pendukung yang kamu butuhkan! 📚 Aku bisa membantu kamu dengan pertanyaan atau masalah yang terkait dengan kebijakan sekolah, jadwal, administrasi, dan materi pembelajaran dasar! 📝', 'aska', '2025-12-01 09:51:15.351820+0700', 5136, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (15, 1531368830, 'fajartester', 'sapa kamu?', 'user', '2025-12-01 10:00:12.375712+0700', NULL, NULL, 'telegram') ON CONFLICT DO NOTHING;
INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (16, 1531368830, 'ASKA', 'Halo! 🤗 Aku ASKA! 🤗 Aku adalah asisten virtual yang siap membantu kamu dengan informasi dan layanan pendukung yang kamu butuhkan! 📚 Aku disiapkan untuk membantu kamu dengan pertanyaan atau masalah yang terkait dengan kebijakan sekolah, jadwal, administrasi, dan materi pembelajaran dasar! 📝', 'aska', '2025-12-01 10:00:13.348047+0700', 4132, NULL, 'telegram') ON CONFLICT DO NOTHING;
