INSERT INTO "chat_logs" ("id", "user_id", "username", "text", "role", "created_at", "response_time_ms", "topic", "channel") VALUES (18, 1, 'ASKA', 'Halo! 🤗 Aku ASKA, aku tahu jawabannya! 🤓 Libur semester pertama mulai tanggal 20 Desember 2025 dan berakhir tanggal 3 Januari 2026. Sementara itu, libur semester kedua mulai tanggal 27 Juni 2026 dan berakhir tanggal 11 Juli 2026. 📆', 'aska', '2025-12-05 08:09:41.629059+0700', 2197, 'web', 'web') ON CONFLICT DO NOTHING;
